--
-- Table structure for table `status`
--

DROP TABLE IF EXISTS `status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `status` (
  `status_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `satisfaction_score` tinyint unsigned DEFAULT NULL,
  `customer_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `churn_label` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `churn_score` tinyint unsigned DEFAULT NULL,
  `cltv` int unsigned DEFAULT NULL,
  PRIMARY KEY (`status_id`),
  UNIQUE KEY `uq_status_customer` (`customer_id`),
  KEY `idx_status_customer_status` (`customer_status`),
  CONSTRAINT `fk_status_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_status_churn_label` CHECK ((`churn_label` in (_utf8mb4'Yes',_utf8mb4'No'))),
  CONSTRAINT `chk_status_churn_score` CHECK ((`churn_score` between 0 and 100)),
  CONSTRAINT `chk_status_customer_status` CHECK ((`customer_status` in (_utf8mb4'Churned',_utf8mb4'Stayed',_utf8mb4'Joined'))),
  CONSTRAINT `chk_status_satisfaction` CHECK ((`satisfaction_score` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

